1	<!DOCTYPE html>
2	<html lang="zh-Hant">
3	<head>
4	<meta charset="UTF-8">
5	<title>{% block title %}BNI大台南南區{% endblock %}</title>
6	<link rel="preconnect" href="https://fonts.googleapis.com">
7	<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@400;500;700;900&display=swap" rel="stylesheet">
8	<style>
9	  :root{
10	    --red:#CF2030; --red-dark:#9B1F27; --ink:#000000; --paper:#FAF7F2;
11	    --line:#E5DFD3; --gold:#B08D57; --sub:#6B665D;
12	  }
13	  *{box-sizing:border-box;margin:0;padding:0;}
14	  body{font-family:"Helvetica Neue",Arial,"PingFang TC","Microsoft JhengHei","Noto Sans TC",sans-serif;color:var(--ink);background:var(--paper);line-height:1.7;}
15	  a{text-decoration:none;color:inherit;}
16	  .wrap{max-width:1120px;margin:0 auto;padding:0 32px;}
17	  header{position:sticky;top:0;background:#fff;border-bottom:1px solid var(--line);z-index:10;}
18	  .navbar{display:flex;align-items:center;justify-content:space-between;padding:18px 0;}
19	  .logo{font-size:20px;font-weight:900;color:var(--red-dark);letter-spacing:1px;}
20	  .logo span{font-weight:400;font-size:13px;color:var(--sub);display:block;margin-top:2px;letter-spacing:2px;}
21	  nav ul{display:flex;gap:32px;list-style:none;font-size:15px;font-weight:500;}
22	  nav a:hover{color:var(--red);}
23	  .nav-actions{display:flex;align-items:center;gap:14px;}
24	  .hamburger-btn{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:5px;width:42px;height:42px;flex-shrink:0;background:#fff;border:1px solid var(--line);border-radius:8px;cursor:pointer;padding:0;transition:border-color .2s,background .2s;}
25	  .hamburger-btn span{display:block;width:20px;height:2px;background:var(--red-dark);border-radius:2px;transition:background .2s;}
26	  .hamburger-btn:hover{border-color:var(--red);background:#FBF3F3;}
27	  .btn{display:inline-block;background:var(--red);color:#fff;padding:12px 28px;border-radius:4px;font-weight:700;font-size:14px;letter-spacing:1px;transition:background .2s;border:none;cursor:pointer;}
28	  .btn:hover{background:var(--red-dark);}
29	  .btn-outline{background:transparent;border:2px solid #fff;color:#fff;}
30	  .btn-outline:hover{background:#fff;color:var(--red-dark);}
31	  .badge{display:inline-block;background:var(--gold);color:#fff;padding:6px 18px;border-radius:20px;font-size:13px;font-weight:700;letter-spacing:2px;margin-bottom:20px;}
32	  .hero{background:var(--ink);color:#fff;padding:100px 0 90px;text-align:center;position:relative;}
33	  .hero::after{content:"";position:absolute;bottom:0;left:0;right:0;height:6px;background:var(--red);}
34	  .hero h1{font-size:52px;font-weight:900;letter-spacing:2px;margin-bottom:18px;}
35	  .hero p{font-size:18px;color:#D8D0C0;max-width:600px;margin:0 auto 40px;}
36	  .hero .cta-row{display:flex;gap:16px;justify-content:center;flex-wrap:wrap;}
37	  section{padding:90px 0;}
38	  .section-tag{color:var(--red);font-weight:700;font-size:13px;letter-spacing:3px;text-transform:uppercase;margin-bottom:12px;}
39	  h2{font-size:34px;font-weight:900;margin-bottom:16px;}
40	  .lead{color:var(--sub);font-size:16px;max-width:640px;margin-bottom:56px;}
41	  .notice-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:24px;}
42	  .notice-card{background:#fff;border:1px solid var(--line);border-radius:8px;padding:32px 20px;text-align:center;}
43	  .notice-num{width:44px;height:44px;border-radius:50%;background:var(--red);color:#fff;font-weight:700;font-size:18px;display:flex;align-items:center;justify-content:center;margin:0 auto 16px;}
44	  .notice-card h3{font-size:16px;font-weight:700;margin-bottom:6px;}
45	  .notice-card p{font-size:13px;color:var(--sub);}
46	  .value{background:#fff;}
47	  .value-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:32px;}
48	  .value-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:32px 28px;box-shadow:0 4px 16px rgba(42,40,41,.06);transition:transform .28s ease,box-shadow .28s ease,border-color .28s ease;}
49	  .value-card:hover{transform:translateY(-8px);box-shadow:0 24px 44px rgba(162,32,38,.2);border-color:var(--red);}
50	  .value-card h3{font-size:19px;font-weight:900;margin-bottom:10px;color:var(--red-dark);}
51	  .value-card p{font-size:14px;color:var(--sub);}
52	  .glory{background:var(--red);color:#fff;}
53	  .glory .section-tag{color:#F0D9DA;}
54	  .glory h2{color:#fff;}
55	  .glory .lead{color:#F0D9DA;}
56	  .glory-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:24px;}
57	  .glory-card{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.25);border-radius:8px;padding:28px 24px;}
58	  .glory-card .num{font-size:36px;font-weight:900;margin-bottom:8px;}
59	  .glory-card p{font-size:14px;color:#F0D9DA;}
60	  footer{background:var(--ink);color:#D8D0C0;padding:48px 0 32px;}
61	  .links-modal-overlay{display:none;position:fixed;inset:0;background:rgba(42,40,41,.72);z-index:100;align-items:center;justify-content:center;padding:24px;}
62	  .links-modal-overlay.open{display:flex;}
63	  .links-modal-box{background:var(--paper);border-radius:20px;max-width:720px;width:100%;max-height:85vh;position:relative;box-shadow:0 30px 70px rgba(0,0,0,.35);}
64	  .links-modal-scroll{max-height:85vh;overflow-y:auto;padding:48px 44px;}
65	  .links-modal-close{position:absolute;top:16px;right:20px;background:none;border:none;font-size:32px;line-height:1;color:var(--sub);cursor:pointer;z-index:2;}
66	  .links-modal-close:hover{color:var(--red);}
67	  .links-modal-section{margin-bottom:44px;}
68	  .links-modal-section:last-child{margin-bottom:0;}
69	  .links-modal-section h2{font-size:24px;margin-bottom:18px;}
70	  .quicklink-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;}
71	  .quicklink-card{display:block;width:100%;background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px 18px;text-align:center;font-weight:700;font-size:15px;font-family:inherit;color:var(--red-dark);box-shadow:0 4px 14px rgba(42,40,41,.06);transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease;cursor:pointer;}
72	  .quicklink-card:hover{transform:translateY(-5px);box-shadow:0 16px 30px rgba(162,32,38,.18);border-color:var(--red);}
73	  .traditions{background:#fff;}
74	  .traditions-columns{display:grid;grid-template-columns:1fr 1fr;gap:56px;margin-top:20px;}
75	  .col-title{font-size:18px;margin-bottom:16px;display:flex;flex-direction:column;gap:2px;}
76	  .col-title span{font-size:12px;color:var(--gold);font-weight:400;letter-spacing:1px;}
77	  @media(max-width:640px){.traditions-columns{grid-template-columns:1fr;}}
78	  .tradition-list,.ethics-list{list-style:none;counter-reset:item;}
79	  .tradition-list li,.ethics-list li{counter-increment:item;position:relative;padding:12px 0 12px 40px;border-bottom:1px solid var(--line);font-size:14px;color:var(--sub);}
80	  .tradition-list li:last-child,.ethics-list li:last-child{border-bottom:none;}
81	  .tradition-list li::before,.ethics-list li::before{content:counter(item);position:absolute;left:0;top:12px;width:26px;height:26px;border-radius:50%;background:var(--red);color:#fff;font-size:13px;font-weight:700;display:flex;align-items:center;justify-content:center;}
82	  .tradition-list li b{display:block;color:var(--ink);font-weight:700;font-size:15px;margin-bottom:2px;}
83	  .tradition-list li span{color:var(--gold);font-size:13px;}
84	  .ethics-list li{color:var(--ink);line-height:1.8;}
85	  .foot-row{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:16px;}
86	  .foot-slogan{font-size:15px;font-weight:700;color:#fff;}
87	  .foot-links a{margin-left:20px;font-size:13px;color:#D8D0C0;}
88	  .foot-links a:hover{color:#fff;}
