input.command:
cd /Users/bymyway/.claude/projects
python3 - <<'EOF'
import json, glob, os, datetime, re

cutoff = datetime.datetime(2026,7,8,16,0, tzinfo=datetime.timezone.utc)
files = glob.glob("**/*.jsonl", recursive=True)

seen = {}
keywords = ["跳HTML", "跳chrome", "跳Chrome", "跳出Chrome", "真正的Chrome", "open -a", "用Chrome", "沒跳", "沒有跳", "chrome跳", "Chrome跳"]

for f in files:
    try:
        with open(f, "r", encoding="utf-8", errors="ignore") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except Exception:
                    continue
                if obj.get("type") != "user":
                    continue
                msg = obj.get("message", {})
                if msg.get("role") != "user":
                    continue
                content = msg.get("content")
                text = ""
                if isinstance(content, str):
                    text = content
                elif isinstance(content, list):
                    for c in content:
                        if isinstance(c, dict) and c.get("type") == "text":
                            text += c.get("text", "")
                if "Stop hook feedback" in text:
                    continue
                stripped = re.sub(r"<system-reminder>.*?</system-reminder>", "", text, flags=re.S).strip()
                if not any(k.lower() in stripped.lower() for k in keywords):
                    continue
                ts = obj.get("timestamp", "")
                try:
                    tsdt = datetime.datetime.fromisoformat(ts.replace("Z","+00:00"))
                except Exception:
                    continue
                if tsdt < cutoff:
                    continue
                key = (ts, stripped[:80])
                seen[key] = stripped[:300]
    except Exception:
        pass

for k in sorted(seen.keys()):
    ts, _ = k
    print(f"[{ts}]", seen[k].replace("\n"," ")[:220])
print()
print("去重後總筆數:", len(seen))
EOF

